const svgPaths = {
  home:'<path d="M3 10.5 12 3l9 7.5v9a1.5 1.5 0 0 1-1.5 1.5H15v-6H9v6H4.5A1.5 1.5 0 0 1 3 19.5z"/>',
  work:'<path d="m5 12 4 4L19 6"/>', search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>', filter:'<path d="M4 5h16l-6 7v6l-4 2v-8z"/>',
  sort:'<path d="M8 6h9M8 12h7M8 18h5"/><path d="m4 4-2 2 2 2M2 6v12"/>', group:'<rect x="4" y="5" width="16" height="4" rx="1"/><rect x="4" y="15" width="16" height="4" rx="1"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6V21h-4v-.1a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H3v-4h.1a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1a1.7 1.7 0 0 0 1.9.3A1.7 1.7 0 0 0 10 3h4a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.1v4H21a1.7 1.7 0 0 0-1.6 1z"/>',
  plus:'<path d="M12 5v14M5 12h14"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>', import:'<path d="M12 3v12m-4-4 4 4 4-4"/><path d="M5 20h14"/>', export:'<path d="M12 21V9m-4 4 4-4 4 4"/><path d="M5 4h14"/>',
  trash:'<path d="M4 7h16M9 7V4h6v3m-9 0 1 14h10l1-14M10 11v6m4-6v6"/>', menu:'<path d="M4 7h16M4 12h16M4 17h16"/>', chevron:'<path d="m8 10 4 4 4-4"/>', edit:'<path d="m4 20 4.5-1 10-10-3.5-3.5-10 10zM14 6l3.5 3.5"/>', board:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M8 4v16M8 10h13"/>', people:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8"/>', copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/>',
  bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>', more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>', columns:'<path d="M4 5h16v14H4zM9 5v14M15 5v14"/>', calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>', layout:'<rect x="3" y="3" width="8" height="8" rx="1"/><rect x="13" y="3" width="8" height="8" rx="1"/><rect x="3" y="13" width="8" height="8" rx="1"/><rect x="13" y="13" width="8" height="8" rx="1"/>', list:'<path d="M8 6h13M8 12h13M8 18h13"/><circle cx="4" cy="6" r="1"/><circle cx="4" cy="12" r="1"/><circle cx="4" cy="18" r="1"/>', archive:'<path d="M3 6h18v4H3zM5 10v10h14V10M10 14h4"/>', star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.2l-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>', user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>'
};
const icon = (name) => `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${svgPaths[name]||svgPaths.board}</svg>`;

class AppView {
  constructor(root) { this.root = root; }
  applyDisplay(model) {
    const systemDark = typeof matchMedia === "function" && matchMedia("(prefers-color-scheme: dark)").matches;
    document.documentElement.dataset.theme = model.settings.theme === "system" ? (systemDark ? "dark" : "light") : model.settings.theme;
    document.documentElement.dataset.fontSize = model.settings.fontSize;
    document.documentElement.dataset.contrast = model.settings.highContrast ? "high" : "normal";
    document.documentElement.dataset.motion = model.settings.reduceMotion ? "reduced" : "normal";
    document.documentElement.dataset.stickyColumn = model.settings.stickyFirstColumn ? "on" : "off";
    document.documentElement.style.setProperty("--accent", model.settings.accentColor);
    document.documentElement.style.setProperty("--focus", model.settings.accentColor);
  }
  render(model) {
    this.applyDisplay(model);
    document.documentElement.dataset.density = model.settings.density;
    this.root.innerHTML = `<div class="app-shell">${this.sidebar(model)}<main class="workspace">${this.topbar(model)}${this.content(model)}</main></div><input id="import-file" class="sr-only" type="file" accept="application/json,.json,text/csv,.csv" data-action="import-file"><input id="avatar-file" class="sr-only" type="file" accept="image/png,image/jpeg,image/webp" data-action="avatar-file"><div id="overlay-root"></div>`;
  }

  renderLogin(auth, model) {
    this.applyDisplay(model);
    const lastLogin = auth.lastLogin ? this.time(auth.lastLogin) : "First sign-in";
    this.root.innerHTML = `<main class="login-shell"><section class="login-brand-panel"><div class="login-brand"><span class="brand-mark">J</span><div><strong>Jarc</strong><small>Operations Database</small></div></div><div class="login-context"><div class="eyebrow">Secure local workspace</div><h1>Work stays organized.</h1><p>Manage boards, records, assignments, notifications, and personal views in one focused workspace.</p><div class="login-signals"><span><i></i> Local autosave</span><span><i></i> Session protection</span><span><i></i> Adaptive display settings</span></div></div><small class="login-version">Jarc Database</small></section><section class="login-panel"><form class="login-form" data-action="login-form" novalidate><div class="login-mobile-brand"><span class="brand-mark">J</span><strong>Jarc</strong></div><div class="eyebrow">${auth.lockedScreen ? "Workspace locked" : "Welcome back"}</div><h2>${auth.lockedScreen ? "Unlock Jarc" : "Sign in to Jarc"}</h2><p>${auth.lockedScreen ? "Enter your credentials to continue where you left off." : "Use your workspace account to continue."}</p>${auth.error ? `<div class="login-error" role="alert">${this.escape(auth.error)}</div>` : ""}<label>Username<input name="username" autocomplete="username" required value="${this.escape(auth.rememberedUsername)}" placeholder="Enter username" autofocus></label><label>Password<div class="password-field"><input name="password" type="password" autocomplete="current-password" required placeholder="Enter password" data-action="password-input"><button type="button" data-action="toggle-password" aria-label="Show password">Show</button></div><small id="caps-warning" class="caps-warning" hidden>Caps Lock is on</small></label><div class="login-options"><label><input type="checkbox" name="rememberUsername" ${auth.rememberedUsername ? "checked" : ""}> Remember username</label><label><input type="checkbox" name="rememberSession"> Keep me signed in</label></div><button class="button primary login-submit" type="submit">${auth.lockedScreen ? "Unlock workspace" : "Sign in"}</button><small class="last-login">Last login: ${lastLogin}</small></form></section></main>`;
  }

  sidebar(model) {
    return `<aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">J</span><div class="brand-copy"><strong>Jarc</strong><small>Operations Database</small></div><button class="sidebar-collapse-top" data-action="collapse-nav" aria-label="Collapse sidebar" title="Collapse sidebar">${icon("chevron")}</button></div><nav aria-label="Primary navigation">
      <button class="nav-item ${model.screen === "home" ? "active" : ""}" data-action="nav" data-screen="home" data-tooltip="Home">${icon("home")}<span class="nav-text">Home</span></button>
      <button class="nav-item ${model.screen === "mywork" ? "active" : ""}" data-action="nav" data-screen="mywork" data-tooltip="My work">${icon("work")}<span class="nav-text">My work</span><span class="nav-count">${model.myWork.length}</span></button>
      <button class="nav-item" data-action="command-palette" data-tooltip="Search">${icon("search")}<span class="nav-text">Search</span><span class="nav-shortcut">Ctrl K</span></button>
      <div class="workspace-heading"><p class="nav-label">Workspaces</p><button class="mini-button" data-action="create-workspace" aria-label="Create workspace" title="Create workspace">${icon("plus")}</button></div>
      <button class="workspace-switch" data-action="workspace-menu" data-tooltip="${this.escape(model.workspace.name)}"><span class="workspace-icon" style="background:${model.workspace.color}">${model.workspace.name[0]}</span><span class="workspace-name"><strong>${this.escape(model.workspace.name)}</strong><small>${model.workspace.boards.length} boards</small></span>${icon("chevron")}</button><button class="workspace-collapse" data-action="toggle-workspace-section" aria-label="Collapse workspace boards" title="Collapse workspace boards">${icon("chevron")}</button>
      <div class="nav-tree">${model.workspace.boards.map((board) => `<div class="board-nav ${model.screen === "board" && model.currentBoardId === board.id ? "selected" : ""}"><button class="tree-item" data-action="open-board" data-id="${board.id}" data-tooltip="${this.escape(board.name)}"><span class="tree-icon">${icon("board")}</span><span class="nav-text">${this.escape(board.name)}</span>${board.favorite ? '<span class="favorite-indicator">★</span>' : ""}</button><button class="board-menu-button" data-action="board-menu" data-id="${board.id}" aria-label="Board options" title="Board options">${icon("more")}</button></div>`).join("")}<button class="new-board-nav" data-action="new-board">${icon("plus")} <span class="nav-text">New board</span></button></div>
    </nav><div class="sidebar-footer"><button class="sidebar-settings" data-action="settings" title="Settings">${icon("settings")}<span>Settings</span></button><div class="sidebar-save"><span class="presence-dot"></span><span>Saved locally</span></div></div></aside>`;
  }

  topbar(model) {
    const avatar = model.profile.avatar ? `<img src="${model.profile.avatar}" alt="">` : this.escape(model.profile.initials);
    return `<header class="topbar"><div class="top-context"><button class="icon-button mobile-only" data-action="toggle-nav" aria-label="Open navigation">${icon("menu")}</button><span class="enterprise">Enterprise</span></div><div class="top-actions"><span class="save-state"><i></i> Saved</span><button class="icon-button top-search" data-action="command-palette" aria-label="Open command palette" title="Search Jarc (Ctrl+K)">${icon("search")}</button><button class="notification-button" data-action="notifications" aria-label="Notifications" title="Notifications">${icon("bell")}${model.unreadCount ? `<b>${model.unreadCount > 9 ? "9+" : model.unreadCount}</b>` : ""}</button><button class="invite-button" data-action="invite">${icon("people")} Invite</button><button class="profile profile-button" data-action="profile-menu" style="background:${model.profile.color}" aria-label="Open profile">${avatar}<i class="presence presence-${model.profile.presence.toLowerCase()}"></i></button></div></header>`;
  }

  content(model) {
    if (model.screen === "home") return this.home(model);
    if (model.screen === "mywork") return this.myWork(model);
    return this.boardScreen(model);
  }

  home(model) {
    const total = model.workspace.boards.reduce((sum, board) => sum + board.records.length, 0);
    return `<section class="page-head"><div><div class="eyebrow">${this.escape(model.workspace.name)} workspace</div><h1>Welcome, ${this.escape(model.profile.name.split(" ")[0])}</h1><p>Open a board or create a new workflow.</p></div><button class="button primary" data-action="new-board">${icon("plus")} New board</button></section><section class="workspace-summary"><div><span>Boards</span><strong>${model.workspace.boards.length}</strong></div><div><span>Total records</span><strong>${total}</strong></div><div><span>Assigned to me</span><strong>${model.myWork.filter((record) => record.workspaceId === model.workspace.id).length}</strong></div></section>${model.favoriteBoards.length ? this.boardStrip("Favorites",model.favoriteBoards) : ""}${model.recentBoardItems.length ? this.boardStrip("Recent boards",model.recentBoardItems) : ""}<section class="boards-section"><div class="section-heading"><h2>Your boards</h2><button data-action="new-board">${icon("plus")} Add board</button></div><div class="board-grid">${model.workspace.boards.map((board) => `<article class="board-tile"><button data-action="open-board" data-id="${board.id}"><span class="board-tile-icon">${icon("board")}</span><span><strong>${this.escape(board.name)}</strong><small>${board.records.length} records · ${board.activity.length} updates</small></span><b>${icon("chevron")}</b></button></article>`).join("")}</div></section>`;
  }
  boardStrip(title, boards) { return `<section class="board-strip"><div class="section-heading"><h2>${title}</h2></div><div>${boards.map((board) => `<button data-action="open-record-board" data-board="${board.id}" data-workspace="${board.workspaceId}"><span>${icon("board")}</span><strong>${this.escape(board.name)}</strong><small>${this.escape(board.workspaceName || "")}</small></button>`).join("")}</div></section>`; }

  myWork(model) {
    const rows = model.myWork;
    return `<section class="page-head"><div><div class="eyebrow">Assigned to ${this.escape(model.profile.initials)}</div><h1>My work</h1><p>Items assigned to you across every workspace and board.</p></div></section><section class="data-region"><div class="group-title"><span class="status-dot landing"></span>Assigned items <small>${rows.length}</small></div>${rows.length ? this.crossBoardTable(rows) : this.blank("work", "Nothing assigned yet", `Choose ${this.escape(model.profile.initials)} as the owner of a record and it will appear here.`)}</section>`;
  }

  boardScreen(model) {
    return `<section class="board-head"><div class="board-breadcrumb">${this.escape(model.workspace.name)} / ${this.escape(model.board.name)}</div><div class="title-row"><div><h1><input class="board-title-input" data-action="board-title-inline" value="${this.escape(model.board.name)}" aria-label="Board name"></h1><button class="board-description" data-action="edit-description">${this.escape(model.board.description || "Add a clear description for this board")}</button></div><div class="board-actions"><button class="icon-button ${model.board.favorite ? "active" : ""}" data-action="toggle-favorite" aria-label="Favorite board" title="Favorite">${icon("star")}</button><button class="button secondary" data-action="import">${icon("import")} Import</button><button class="button secondary" data-action="export" ${model.rows.length ? "" : "disabled"}>${icon("export")} Export</button><button class="button primary" data-action="open-form">${icon("plus")} New record</button><button class="icon-button" data-action="board-menu" data-id="${model.board.id}" title="Board actions">${icon("more")}</button></div></div>${this.tabs(model)}</section>${this.toolbar(model)}${model.selected.size ? this.bulkBar(model) : ""}${this.boardView(model)}`;
  }

  tabs(model) {
    const views=[["table","Main Table","layout"],["list","List","list"],["kanban","Board","board"],["calendar","Calendar","calendar"]];
    return `<div class="view-tabs">${views.map(([v,label,ic])=>`<button class="${model.currentView===v&&!model.showArchived?"active":""}" data-action="set-view" data-view="${v}">${icon(ic)} ${label}</button>`).join("")}<button class="${model.showArchived?"active":""}" data-action="archived-view">${icon("archive")} Archived <small>${model.archivedCount}</small></button><button data-action="saved-views">${icon("star")} Saved views</button></div>`;
  }

  toolbar(model) {
    const statuses=model.statusColumn?.options?.length?model.statusColumn.options:[...new Set(model.rows.map(r=>model.statusColumn?r[model.statusColumn.key]:"").filter(Boolean))];
    return `<section class="board-tools"><div class="tool-left"><label class="search-field">${icon("search")}<input id="board-search" data-action="search" value="${this.escape(model.query)}" placeholder="Search records..."><kbd>/</kbd></label>${model.statusColumn?`<label class="select-control">${icon("filter")}<select data-action="filter"><option>All</option>${statuses.map(status=>`<option ${model.status===status?"selected":""}>${this.escape(status)}</option>`).join("")}</select></label>`:""}<button class="tool-button" data-action="sort">${icon("sort")} Sort</button><button class="tool-button ${model.grouped?"active":""}" data-action="group">${icon("group")} Group</button></div><div class="tool-right"><button class="tool-button" data-action="manage-columns">${icon("columns")} Columns</button><button class="tool-button" data-action="density-menu">Density</button><button class="icon-button" data-action="view-overflow" title="More view options">${icon("more")}</button><button class="button primary compact-primary" data-action="open-form">${icon("plus")} New record</button></div></section>`;
  }

  bulkBar(model) { return `<div class="bulk-bar"><strong>${model.selected.size} selected</strong>${model.statusColumn?'<button data-action="bulk-status">Set status</button>':""}${model.ownerColumn?'<button data-action="bulk-owner">Assign owner</button>':""}${model.priorityColumn?'<button data-action="bulk-priority">Set priority</button>':""}<button data-action="delete-selected">${icon("trash")} Delete</button><button data-action="clear-selection">Clear</button></div>`; }
  boardView(model) {
    const rows=model.visibleRows; if(!rows.length)return this.blank("records",model.showArchived?"No archived records":"No records yet",model.showArchived?"Archived records will appear here.":"Create a record or import data to get started.",!model.showArchived);
    if(model.currentView==="list") return this.listView(rows,model);
    if(model.currentView==="kanban") return this.kanbanView(rows,model);
    if(model.currentView==="calendar") return this.calendarView(rows,model);
    if(model.grouped&&model.groupColumn){return `<section class="data-region grouped-region">${model.board.groups.map(g=>{const gr=rows.filter(r=>r[model.groupColumn.key]===g);return `<div class="group-block"><div class="group-title"><span class="group-marker"></span>${this.escape(g)} <small>${gr.length}</small></div>${this.table(gr,model)}</div>`}).join("")}</section>`;}
    return `<section class="data-region"><div class="group-title"><span class="group-marker group-new"></span>All records <small>${rows.length}</small></div>${this.table(rows,model)}</section>`;
  }
  listView(rows,model){return `<section class="modern-list">${rows.map(row=>`<button class="list-card" data-action="edit" data-id="${row.id}"><span class="record-avatar">${this.escape(String(row.serial||"R")[0])}</span><span><strong>${this.escape(row.serial||"Untitled")}</strong><small>${this.escape(row.notes||"No notes")}</small></span><span class="list-meta">${row.status?`<b class="status-chip">${this.escape(row.status)}</b>`:""}${this.date(row.dueDate||row.received)}</span>${icon("chevron")}</button>`).join("")}</section>`;}
  kanbanView(rows,model){const key=model.statusColumn?.key||model.groupColumn?.key;const groups=model.statusColumn?.options?.length?model.statusColumn.options:model.board.groups;return `<section class="kanban-board">${groups.map(g=>{const items=rows.filter(r=>r[key]===g);return `<div class="kanban-column"><header><strong>${this.escape(g)}</strong><span>${items.length}</span></header><div>${items.map(r=>`<button class="kanban-card" data-action="edit" data-id="${r.id}"><strong>${this.escape(r.serial)}</strong><small>${this.escape(r.owner||"Unassigned")}</small><span>${this.escape(r.priority||"")}</span></button>`).join("")||'<p class="kanban-empty">No records</p>'}</div></div>`}).join("")}</section>`;}
  calendarView(rows,model){const dateKey=model.sortColumn?.key||"received";const dated=rows.filter(r=>r[dateKey]);return `<section class="calendar-view"><div class="calendar-head"><strong>Records by date</strong><small>${dated.length} scheduled</small></div><div class="calendar-grid">${dated.sort((a,b)=>String(a[dateKey]).localeCompare(String(b[dateKey]))).map(r=>`<button class="calendar-record" data-action="edit" data-id="${r.id}"><time>${this.date(r[dateKey])}</time><span><strong>${this.escape(r.serial)}</strong><small>${this.escape(r.status||"")}</small></span></button>`).join("")||'<div class="calendar-empty">Add a date to a record to see it here.</div>'}</div></section>`;}

  table(rows, model) {
    return `<div class="table-wrap"><table class="editable-table"><thead><tr><th class="check-col"><input type="checkbox" data-action="select-all" ${rows.every((row) => model.selected.has(row.id)) ? "checked" : ""}></th>${model.visibleColumns.map((column) => `<th data-column-key="${column.key}"><div class="column-header-inline"><input data-action="column-label-inline" data-key="${column.key}" value="${this.escape(column.label)}" aria-label="Rename ${this.escape(column.label)}"><button data-action="column-editor" data-key="${column.key}" aria-label="Column settings">${icon("settings")}</button>${column.connection ? '<i class="connected-dot" title="Connection configured"></i>' : ""}</div></th>`).join("")}<th class="actions-col"><button class="column-header-add" data-action="add-column" aria-label="Add column">${icon("plus")}</button></th></tr></thead><tbody>${rows.map((row) => this.row(row, model)).join("")}<tr class="quick-add-row"><td></td><td colspan="${model.visibleColumns.length + 1}"><button data-action="new-item">${icon("plus")} New record</button></td></tr></tbody></table></div>`;
  }
  row(row, model) {
    return `<tr class="${model.selected.has(row.id) ? "is-selected" : ""} ${row.pinned?"is-pinned":""}"><td class="check-col"><input type="checkbox" data-action="select" data-id="${row.id}" ${model.selected.has(row.id) ? "checked" : ""}></td>${model.visibleColumns.map((column) => `<td data-column-key="${column.key}">${this.cellEditor(row,column,model)}</td>`).join("")}<td class="row-actions"><button class="row-open-button" data-action="edit" data-id="${row.id}" title="Open record">Open</button><button class="row-more-button" data-action="record-menu" data-id="${row.id}" aria-label="Record actions" title="Record actions">${icon("more")}</button></td></tr>`;
  }

  cellEditor(row, column, model) {
    const attrs = `data-action="cell-edit" data-id="${row.id}" data-field="${column.key}" data-column-key="${column.key}" aria-label="Edit ${column.label}"`;
    const value=row[column.key] ?? column.defaultValue ?? "";
    if (column.type === "group") return `<select class="inline-editor" ${attrs}>${model.board.groups.map((option) => `<option ${value === option ? "selected" : ""}>${this.escape(option)}</option>`).join("")}</select>`;
    if (column.type === "owner") return `<select class="inline-editor" ${attrs}>${["Unassigned",model.profile.initials,"Engineering","QA Team"].map((option) => `<option ${value === option ? "selected" : ""}>${option}</option>`).join("")}</select>`;
    if (column.type === "status") { const options=[...new Set([value,...(column.options.length?column.options:["New","In Progress","Waiting","Completed","Cancelled","Review","Defective","Clear"])].filter(Boolean))]; return `<select class="inline-editor status-editor" ${attrs}>${options.map((option) => `<option ${value === option ? "selected" : ""}>${this.escape(option)}</option>`).join("")}</select>`; }
    if (column.type === "priority") return `<select class="inline-editor priority-editor" ${attrs}>${["Low","Medium","High","Critical"].map((option) => `<option ${value === option ? "selected" : ""}>${option}</option>`).join("")}</select>`;
    if (column.type === "dropdown") return `<select class="inline-editor" ${attrs}><option value="">Select...</option>${column.options.map((option)=>`<option ${value===option?"selected":""}>${this.escape(option)}</option>`).join("")}</select>`;
    if (column.type === "checkbox") return `<input class="inline-checkbox" ${attrs} type="checkbox" ${value?"checked":""}>`;
    const inputType={date:"date",number:"number",email:"email",phone:"tel",link:"url"}[column.type] || "text";
    return `<input class="inline-editor" ${attrs} type="${inputType}" value="${this.escape(value)}" ${column.required ? "required" : ""} placeholder="${column.type === "date" ? "" : "Add value"}">`;
  }

  crossBoardTable(rows) { return `<div class="table-wrap"><table><thead><tr><th>Record</th><th>Board</th><th>Workspace</th><th>Status</th><th>Priority</th><th>Due</th></tr></thead><tbody>${rows.map((row) => `<tr><td><button class="link-button" data-action="open-record-board" data-board="${row.boardId}" data-workspace="${row.workspaceId}">${this.escape(row.serial)}</button></td><td>${this.escape(row.boardName)}</td><td>${this.escape(this.workspaceName(row.workspaceId))}</td><td>${row.status?`<span class="status status-${String(row.status).toLowerCase()}">${this.escape(row.status)}</span>`:"-"}</td><td>${this.escape(row.priority||"-")}</td><td>${this.date(row.dueDate)}</td></tr>`).join("")}</tbody></table></div>`; }
  workspaceName(id) { return id === "engineering" ? "Engineering" : "Operations"; }
  blank(type, title, text, action = false) { return `<section class="empty-state ${type}"><div class="empty-visual"><span></span><span></span><span></span></div><div class="eyebrow">Blank view</div><h2>${title}</h2><p>${text}</p>${action ? `<button class="button primary" data-action="new-item">${icon("plus")} New item</button>` : ""}</section>`; }

  showBoardForm(board) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><form class="modal small-modal" data-action="board-form"><div class="modal-head"><div><div class="eyebrow">Workspace board</div><h2>${board ? "Rename board" : "New board"}</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><input type="hidden" name="id" value="${board?.id || ""}"><div class="form-grid"><label class="full">Board name <input name="name" required maxlength="60" value="${this.escape(board?.name || "")}" placeholder="Project tracker"></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">${board ? "Save name" : "Create board"}</button></div></form></div>`; }

  showWorkspaceMenu(model) { document.querySelector("#overlay-root").innerHTML = `<div class="popover workspace-popover"><div class="popover-title"><strong>Switch workspace</strong><small>${model.workspaces.length} workspaces</small></div><label class="workspace-search">${icon("search")}<input placeholder="Search workspaces..." data-action="workspace-search"></label><div class="workspace-list">${model.workspaces.map((space) => `<button data-action="switch-workspace" data-id="${space.id}" class="${space.id === model.currentWorkspaceId ? "selected" : ""}"><span class="workspace-icon" style="background:${space.color}">${space.name[0]}</span><span><strong>${this.escape(space.name)}</strong><small>${space.boards.length} boards</small></span>${space.id === model.currentWorkspaceId ? "✓" : ""}</button>`).join("")}</div><div class="popover-footer"><button data-action="create-workspace">${icon("plus")} Create workspace</button><button data-action="workspace-manage">${icon("settings")} Manage workspaces</button></div></div>`; }
  showWorkspaceForm() { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><form class="modal workspace-form" data-action="workspace-form"><div class="modal-head"><div><div class="eyebrow">New workspace</div><h2>Create workspace</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><p class="modal-intro">Create a separate space for a team, department, or workflow.</p><div class="form-grid"><label class="full">Workspace name<input name="name" required maxlength="40" placeholder="e.g. Finance"></label><label>Icon<input name="icon" maxlength="2" value="W" placeholder="W"></label><label>Color<input name="color" type="color" value="#0f9489"></label><label class="full">Description<textarea name="description" rows="3" placeholder="What is this workspace for?"></textarea></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary" type="submit">Create workspace</button></div></form></div>`; }
  showRecordMenu(row) { document.querySelector("#overlay-root").innerHTML = `<div class="popover record-menu-popover"><button data-action="edit" data-id="${row.id}">${icon("edit")} Edit record</button><button data-action="duplicate-record" data-id="${row.id}">${icon("copy")} Duplicate</button><button data-action="pin-item" data-id="${row.id}">${row.pinned?"Unpin":"Pin"} record</button><button data-action="move-item" data-direction="up" data-id="${row.id}">Move up</button><button data-action="move-item" data-direction="down" data-id="${row.id}">Move down</button><button data-action="archive-item" data-id="${row.id}">${row.archived?"Restore":"Archive"}</button>${row.archived?"":`<button class="danger" data-action="delete" data-id="${row.id}">${icon("trash")} Delete</button>`}</div>`; }
  showBoardMenu(board) { document.querySelector("#overlay-root").innerHTML = `<div class="popover board-popover"><button data-action="rename-board" data-id="${board.id}">${icon("edit")} Rename</button><button data-action="duplicate-board" data-id="${board.id}">${icon("copy")} Duplicate</button><button data-action="move-board" data-id="${board.id}">${icon("board")} Move to workspace</button><button data-action="archive-board" data-id="${board.id}">${icon("archive")} ${board.archived?"Restore":"Archive"}</button><button class="danger" data-action="delete-board" data-id="${board.id}">${icon("trash")} Delete</button></div>`; }
  showMore() { document.querySelector("#overlay-root").innerHTML = `<div class="popover more-popover"><button data-action="global-search">${icon("search")} Search all boards</button><button data-action="settings">${icon("settings")} Workspace settings</button><button data-action="shortcuts">? Keyboard shortcuts</button></div>`; }
  showSettings(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay drawer-overlay" data-action="close-overlay"><aside class="settings-drawer"><div class="modal-head"><div><div class="eyebrow">Workspace preferences</div><h2>Settings</h2></div><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><section><h3>Theme</h3><div class="theme-grid">${["light","dark","system"].map((theme) => `<button class="theme-option ${model.settings.theme === theme ? "selected" : ""}" data-action="theme" data-theme="${theme}"><span class="theme-preview ${theme}"><i></i><i></i><i></i></span><strong>${this.cap(theme)}</strong></button>`).join("")}</div></section><section><h3>Accessibility and display</h3><label class="setting-row"><span><strong>Accent color</strong><small>Personalize actions and focus states</small></span><input type="color" data-action="accent-color" value="${model.settings.accentColor}"></label><label class="setting-row"><span><strong>Text size</strong><small>Scale workspace interface text</small></span><select data-action="setting-select" data-key="fontSize">${["small","normal","large"].map((value)=>`<option ${model.settings.fontSize===value?"selected":""}>${this.cap(value)}</option>`).join("")}</select></label>${[["highContrast","High contrast","Strengthen borders and text"],["reduceMotion","Reduce motion","Disable interface animation"],["stickyFirstColumn","Sticky record column","Keep record names visible while scrolling"]].map(([key,label,help])=>`<label class="setting-row"><span><strong>${label}</strong><small>${help}</small></span><input type="checkbox" data-action="setting" data-key="${key}" ${model.settings[key]?"checked":""}></label>`).join("")}<label class="setting-row"><span><strong>Compact rows</strong><small>Fit more items on screen</small></span><input type="checkbox" data-action="density" ${model.settings.density === "compact" ? "checked" : ""}></label></section><section><h3>Data tools</h3><button class="button secondary wide-button" data-action="manage-columns">Configure columns and connections</button><button class="button secondary wide-button" data-action="export-backup">Export full JSON backup</button><p>Import accepts Jarc JSON backups, record JSON, and CSV files.</p></section></aside></div>`; }
  showInvite() { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><form class="modal small-modal" data-action="invite-form"><div class="modal-head"><div><div class="eyebrow">Workspace member</div><h2>Add member</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="form-grid"><label class="full">Email address<input name="email" type="email" required placeholder="name@company.com"></label><label class="full">Role<select name="role"><option>Admin</option><option selected>Editor</option><option>Viewer</option></select></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Add member</button></div></form></div>`; }
  showQuickChoice(title, options, action, id) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal small-modal"><div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="choice-list">${options.map((value) => `<button data-action="${action}" data-id="${id}" data-value="${value}">${value}</button>`).join("")}</div></div></div>`; }
  showConfirm(title, text, action, payload = "") { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal confirm-modal"><div class="confirm-icon">!</div><h2>${this.escape(title)}</h2><p>${this.escape(text)}</p><div class="modal-actions"><button class="button secondary" data-action="close-overlay">Cancel</button><button class="button danger-button" data-action="${action}" data-payload="${this.escape(payload)}">Confirm</button></div></div></div>`; }
  showMessage(title, text) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal confirm-modal"><div class="modal-head"><h2>${this.escape(title)}</h2><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><p>${this.escape(text).replaceAll("\n","<br>")}</p><div class="modal-actions"><button class="button primary" data-action="close-overlay">Done</button></div></div></div>`; }
  showGlobalSearch() { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><form class="modal small-modal" data-action="global-search-form"><div class="modal-head"><div><div class="eyebrow">Every workspace</div><h2>Search all boards</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="form-grid"><label class="full">Search term <input name="term" required autofocus placeholder="Serial, invoice, or note"></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Search</button></div></form></div>`; }
  showGroupManager(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal small-modal"><div class="modal-head"><div><div class="eyebrow">Board structure</div><h2>Manage groups</h2></div><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="manager-list">${model.board.groups.map((group) => `<div class="manager-row"><input data-role="group-name" data-old="${this.escape(group)}" value="${this.escape(group)}"><button data-action="save-group" data-old="${this.escape(group)}">Save</button><button class="danger" data-action="request-delete-group" data-group="${this.escape(group)}" ${model.board.groups.length === 1 ? "disabled" : ""}>Delete</button></div>`).join("")}</div><form class="inline-form" data-action="add-group-form"><input name="name" required placeholder="New group name"><button class="button primary">Add group</button></form></div></div>`; }
  showColumnManager(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal column-modal"><div class="modal-head"><div><div class="eyebrow">Board schema</div><h2>Columns</h2><p>Each board owns its column types, labels, order, and connection keys.</p></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="column-manager-list">${model.board.columns.map((column,index)=>`<button data-action="column-editor" data-key="${column.key}"><span class="column-type-icon">${index+1}</span><span><strong>${this.escape(column.label)}</strong><small>${this.escape(column.type)} · ${column.visible?"Visible":"Hidden"}</small></span><b>${icon("chevron")}</b></button>`).join("")}</div><div class="modal-actions"><button class="button primary" data-action="add-column">+ Add column</button></div></div></div>`; }
  showAddColumn(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><form class="modal column-modal" data-action="add-column-form"><div class="modal-head"><div><div class="eyebrow">Board column</div><h2>Add a typed column</h2><p>Choose how values in this column should be entered and stored.</p></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="column-type-grid">${model.columnTypes.map((item)=>`<label><input type="radio" name="type" value="${item.type}" ${item.type==="text"?"checked":""}><span><strong>${item.label}</strong><small>${item.type}</small></span></label>`).join("")}</div><div class="form-grid"><label class="full">Column name<input name="label" required maxlength="50" placeholder="e.g. Delivery date"></label><label>Default value<input name="defaultValue" placeholder="Optional"></label><label>Dropdown / status options<input name="options" placeholder="Option one, Option two"></label><label class="full checkbox-label"><input type="checkbox" name="required"> Require a value</label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Add column</button></div></form></div>`; }
  showColumnEditor(model, key) { const column=model.board.columns.find((item)=>item.key===key); if(!column)return; document.querySelector("#overlay-root").innerHTML = `<div class="overlay drawer-overlay" data-action="close-overlay"><form class="settings-drawer column-settings-drawer" data-action="edit-column-form"><div class="modal-head"><div><div class="eyebrow">${this.escape(column.type)} column</div><h2>Edit column</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><input type="hidden" name="key" value="${column.key}"><div class="form-grid"><label class="full">Header name<input name="label" required value="${this.escape(column.label)}"></label><label>Default value<input name="defaultValue" value="${this.escape(column.defaultValue)}"></label><label>Options<input name="options" value="${this.escape(column.options.join(", "))}" placeholder="Comma separated"></label><label class="full">Future connector key<input name="connection" value="${this.escape(column.connection)}" placeholder="API field or endpoint"></label><label class="checkbox-label"><input type="checkbox" name="visible" ${column.visible?"checked":""}> Visible</label><label class="checkbox-label"><input type="checkbox" name="required" ${column.required?"checked":""} ${column.key==="serial"?"disabled":""}> Required</label></div><div class="column-actions"><button type="button" data-action="move-column" data-key="${column.key}" data-direction="left">Move left</button><button type="button" data-action="move-column" data-key="${column.key}" data-direction="right">Move right</button><button type="button" data-action="duplicate-column" data-key="${column.key}">Duplicate</button><button type="button" class="danger" data-action="request-delete-column" data-key="${column.key}" ${column.key==="serial"?"disabled":""}>Delete</button></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Save column</button></div></form></div>`; }
  showSavedViews(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><div class="modal small-modal"><div class="modal-head"><div><div class="eyebrow">Reusable filters</div><h2>Saved views</h2></div><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="manager-list">${model.board.savedViews.map((view) => `<div class="manager-row"><button class="view-name" data-action="apply-saved-view" data-id="${view.id}">${this.escape(view.name)}<small>${view.status} · ${view.grouped ? "Grouped" : "Table"}</small></button><button class="danger" data-action="delete-saved-view" data-id="${view.id}">Delete</button></div>`).join("") || '<p class="muted-copy">No saved views yet.</p>'}</div><form class="inline-form" data-action="save-view-form"><input name="name" required placeholder="Name current filters"><button class="button primary">Save current view</button></form></div></div>`; }
  showProfileMenu(model, auth) { const avatar=model.profile.avatar ? `<img src="${model.profile.avatar}" alt="">` : this.escape(model.profile.initials); document.querySelector("#overlay-root").innerHTML = `<div class="profile-popover modern-profile"><div class="profile-summary"><span class="profile large" style="background:${model.profile.color}">${avatar}</span><div><strong>${this.escape(model.profile.name)}</strong><small>${this.escape(model.profile.role)}</small><em><i class="presence presence-${model.profile.presence.toLowerCase()}"></i>${model.profile.presence}</em></div></div><div class="profile-menu-section"><button data-action="profile-settings">${icon("people")} View profile</button><button data-action="settings">${icon("settings")} Account settings</button><button data-action="notifications">${icon("bell")} Notifications <small>${model.unreadCount}</small></button></div><div class="profile-menu-section presence-picker"><span>Status</span>${["Available","Busy","Focus","Offline"].map((value)=>`<button data-action="set-presence" data-value="${value}" class="${model.profile.presence===value?"active":""}"><i class="presence presence-${value.toLowerCase()}"></i>${value}</button>`).join("")}</div><div class="profile-menu-section"><button data-action="workspace-menu">${icon("board")} Switch workspace</button><button data-action="settings">${icon("settings")} Manage workspace</button></div><div class="profile-menu-section"><button class="danger" data-action="request-logout">Sign out</button></div></div>`; }
  showProfileSettings(model) { const avatar=model.profile.avatar ? `<img src="${model.profile.avatar}" alt="">` : this.escape(model.profile.initials); document.querySelector("#overlay-root").innerHTML = `<div class="overlay drawer-overlay" data-action="close-overlay"><form class="settings-drawer" data-action="profile-form"><div class="modal-head"><div><div class="eyebrow">Personal account</div><h2>Profile</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><section class="avatar-editor"><span class="profile xlarge" style="background:${model.profile.color}">${avatar}</span><div><button type="button" class="button secondary" data-action="choose-avatar">Upload photo</button>${model.profile.avatar?'<button type="button" class="text-danger" data-action="remove-avatar">Remove</button>':""}<small>PNG, JPG, or WebP up to 1 MB</small></div></section><section class="profile-fields"><label>Username-synced name<input name="name" readonly value="${this.escape(model.profile.name)}"></label><label>Email<input name="email" type="email" value="${this.escape(model.profile.email)}" placeholder="name@company.com"></label><label>Role<input name="role" value="${this.escape(model.profile.role)}"></label><label>Avatar color<input name="color" type="color" value="${model.profile.color}"></label><label>Start screen<select name="startScreen">${["Last opened board","Home","My work"].map((value)=>`<option ${model.profile.startScreen===value?"selected":""}>${value}</option>`).join("")}</select></label></section><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Save profile</button></div></form></div>`; }
  showNotifications(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay drawer-overlay" data-action="close-overlay"><aside class="settings-drawer notification-drawer"><div class="modal-head"><div><div class="eyebrow">Personal inbox</div><h2>Notifications</h2></div><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="notification-actions"><button data-action="mark-notifications">Mark all read</button><button data-action="clear-notifications">Clear</button></div><div class="notification-list">${model.notifications.map((item)=>`<button class="notification-item ${item.read?"":"unread"}" data-action="open-notification" data-board="${item.boardId}" data-workspace="${item.workspaceId}"><i></i><span><strong>${this.escape(item.text)}</strong><small>${this.time(item.at)}</small></span></button>`).join("") || '<p class="muted-copy">You are all caught up.</p>'}</div></aside></div>`; }
  showCommandPalette(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay command-overlay" data-action="close-overlay"><div class="modal command-modal"><div class="command-search">${icon("search")}<input data-action="command-search" placeholder="Type a command..." autofocus><kbd>Esc</kbd></div><div class="command-list">${[["home","Go to Home"],["mywork","Open My work"],["new-record","Create new item"],["new-board","Create a board"],["notifications","Open notifications"],["profile","Edit profile"],["settings","Open settings"]].map(([command,label])=>`<button data-action="run-command" data-command="${command}" data-label="${label.toLowerCase()}">${label}</button>`).join("")}</div><small class="command-hint">Tip: press Ctrl+K from anywhere.</small></div></div>`; }
  showDescription(model) { document.querySelector("#overlay-root").innerHTML = `<div class="overlay" data-action="close-overlay"><form class="modal small-modal" data-action="description-form"><div class="modal-head"><div><div class="eyebrow">Board context</div><h2>Board description</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="form-grid"><label class="full">Description<textarea name="description" rows="4" maxlength="240" placeholder="What is this board used for?">${this.escape(model.board.description)}</textarea></label></div><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Save description</button></div></form></div>`; }
  showImport(model){document.querySelector("#overlay-root").innerHTML=`<div class="overlay" data-action="close-overlay"><div class="modal import-modal"><div class="modal-head"><div><div class="eyebrow">Bring data into ${this.escape(model.board.name)}</div><h2>Import records</h2></div><button class="icon-button" data-action="close-overlay">${icon("close")}</button></div><div class="import-options"><button data-action="choose-import-file">${icon("import")}<span><strong>CSV or JSON file</strong><small>Import rows or restore a Jarc backup.</small></span></button><button disabled>${icon("columns")}<span><strong>Excel workbook</strong><small>Not supported in this standalone build.</small></span></button></div><form class="paste-import" data-action="paste-import-form"><label>Copy & paste CSV<textarea name="text" rows="7" placeholder="Record / Serial,Owner,Status
ABC-001,JS,New" required></textarea></label><div class="modal-actions"><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">Import pasted data</button></div></form></div></div>`;}
  showRecordForm(model,row=null){ const editing=Boolean(row); const fields=model.board.columns.map(c=>{const val=row?.[c.key]??c.defaultValue??""; if(c.type==="status"||c.type==="priority"||c.type==="group"||c.type==="owner"||c.type==="dropdown"){let opts=c.options?.length?c.options:(c.type==="group"?model.board.groups:c.type==="priority"?["Low","Medium","High","Urgent"]:c.type==="owner"?[model.profile.initials,"Engineering","QA Team","Unassigned"]:["New","In Progress","Waiting","Completed","Cancelled"]);return `<label>${this.escape(c.label)}<select name="${c.key}">${opts.map(o=>`<option ${String(val)===String(o)?"selected":""}>${this.escape(o)}</option>`).join("")}</select></label>`;} if(c.type==="date")return `<label>${this.escape(c.label)}<input type="date" name="${c.key}" value="${this.escape(val)}"></label>`; if(c.type==="checkbox")return `<label class="checkbox-label"><input type="checkbox" name="${c.key}" ${val?"checked":""}> ${this.escape(c.label)}</label>`; return `<label class="${c.key==="notes"?"full":""}">${this.escape(c.label)}${c.key==="notes"?`<textarea name="${c.key}" rows="4">${this.escape(val)}</textarea>`:`<input name="${c.key}" value="${this.escape(val)}" ${c.required?"required":""}>`}</label>`;}).join(""); document.querySelector("#overlay-root").innerHTML=`<div class="overlay drawer-overlay" data-action="close-overlay"><form class="record-drawer" data-action="record-form"><div class="modal-head"><div><div class="eyebrow">${editing?"Record details":"New record"}</div><h2>${editing?this.escape(row.serial||"Record"):"Create record"}</h2></div><button type="button" class="icon-button" data-action="close-overlay">${icon("close")}</button></div><input type="hidden" name="id" value="${row?.id||""}"><div class="record-form-grid">${fields}</div>${editing?`<div class="record-meta"><span>Record ID ${row.id}</span><span>${row.archived?"Archived":"Active"}</span></div>`:""}<div class="modal-actions">${editing?`<button type="button" class="button secondary" data-action="archive-item" data-id="${row.id}">${row.archived?"Restore":"Archive"}</button><button type="button" class="button danger-button" data-action="delete" data-id="${row.id}">Delete</button>`:""}<span class="modal-spacer"></span><button type="button" class="button secondary" data-action="close-overlay">Cancel</button><button class="button primary">${editing?"Save changes":"Create record"}</button></div></form></div>`;}
  showDensityMenu(model){document.querySelector("#overlay-root").innerHTML=`<div class="popover density-popover"><div class="popover-title"><strong>Table density</strong></div><button data-action="set-density" data-value="comfortable" class="${model.settings.density==="comfortable"?"selected":""}">Comfortable</button><button data-action="set-density" data-value="compact" class="${model.settings.density==="compact"?"selected":""}">Compact</button></div>`;}
  showViewOverflow(model){document.querySelector("#overlay-root").innerHTML=`<div class="popover view-overflow"><button data-action="saved-views">${icon("star")} Saved views</button><button data-action="manage-groups">${icon("group")} Manage groups</button><button data-action="undo" ${model.canUndo?"":"disabled"}>Undo last change</button><button data-action="clear-filters">Reset view</button></div>`;}
  showWorkspaceManager(model){this.showSettings(model,"workspace");}
  closeOverlay() { const root=document.querySelector("#overlay-root"); if(root) { root.innerHTML = ""; delete root.dataset.open; } }
  toast(message) { const toast = document.createElement("div"); toast.className="toast"; toast.textContent=message; document.querySelector("#toast-region")?.append(toast); if (!document.querySelector("#toast-region")) { const region=document.createElement("div"); region.id="toast-region"; region.className="toast-region"; document.body.append(region); region.append(toast); } setTimeout(()=>toast.remove(),2800); }
  date(value) { return value ? new Intl.DateTimeFormat("en",{month:"short",day:"numeric",year:"numeric"}).format(new Date(`${value}T00:00:00`)) : "-"; }
  time(value) { return new Intl.DateTimeFormat("en",{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"}).format(new Date(value)); }
  cap(value) { return value[0].toUpperCase()+value.slice(1); }
  escape(value) { return String(value).replace(/[&<>'"]/g,(char)=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[char])); }
}
window.AppView = AppView;
